local M = class("FlowerGivePopControl",LikeOO.OOControlBase)

function M:onEnter()
    M.super.onCreate(self)
end

function M:onHandle(msg , data)
    if msg == 99999 then
        self:closeView()
    elseif msg == "minus_one_btn" then
        self.m_model:addUseNum(-1)
        self.m_view:refreshUI()
    elseif msg == "add_one_btn" then
        self.m_model:addUseNum(1)
        self.m_view:refreshUI()
    elseif msg == "close_btn" then
        self:closeView()
    elseif msg == "btn_flowerBtn" then
        if self.m_model.m_use_num <= 0 then
            GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("flower_text_0059"), delay_close = 2})
            return
        end
        if self.m_model.m_use_num > self.m_model:getMaxNum() then
            GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("flower_text_0067"), delay_close = 2})
            return
        end
        self.m_model:getNetData("send_flower", {target_uid = self.m_model.m_playerId, value = self.m_model.m_use_num}, function(response)
            if response then
                if self:activityOverExamine(response) then
                    return
                end
                RewardUtil:rewardTipsByData(response.reward)
                GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("flower_text_0058"), delay_close = 2})
                self:closeViewEvent()
            end
        end, nil, nil, nil)
    elseif msg == "btn_max" then
        local awardUnit = RewardUtil:getProcessRewardData(self.m_model.m_itemAwardData)
        self.m_model:setUseNum(awardUnit.user_num)
        self.m_view:refreshText()
    end
end

function M:closeViewEvent()
    self:updateMsg("refresh_flowerEvent", {playerId = self.m_model.m_playerId}, "Pops.PlayerInfo")
    self:updateMsg("refresh_flowerEvent", {playerId = self.m_model.m_playerId}, "FlowerFestival.FlowerGiveRank")
    self:updateMsg("refresh_flowerEvent", {playerId = self.m_model.m_playerId}, "FlowerFestival.FlowerAllRank")
    self:closeView()
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView()
        return true
    end
    if response.update == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView()
        return true
    end
    return false
end

function M:destroy()
    M.super.destroy(self)
end

return M